import { Request, Response } from "express";
import { prisma } from "../config/database";
import { AppError } from "../utils/AppError";
import { userCache } from "../config/cache";
import {
  CreateUserInput,
  GetUserByIdParams,
  UpdateUserInput,
} from "../validators/user.validator";

/**
 * POST /api/users
 *
 * Registers a new user in the system.
 *
 * Legacy equivalent:
 *   INSERT INTO my_table(id, Name, Age, Address) VALUES(%s,%s,%s,%s)
 *
 * The `id` is now auto-generated by PostgreSQL via Prisma's @default(autoincrement()).
 * After insertion the full user record is returned so the Python face-capture
 * client can immediately use the `id` for naming image files
 * (`data/user.<id>.<imgId>.jpg`).
 */
export const createUser = async (req: Request, res: Response): Promise<void> => {
  const { name, age, address, department } = req.body as CreateUserInput;

  const user = await prisma.user.create({
    data: { name, age, address, department },
  });

  res.status(201).json({
    success: true,
    message: "User registered successfully",
    data: {
      id: user.id,
      name: user.name,
      age: user.age,
      address: user.address,
      department: user.department,
      createdAt: user.createdAt,
    },
  });
};

/**
 * GET /api/users/:id
 *
 * Retrieves a user by their numeric ID.
 *
 * Legacy equivalent:
 *   SELECT Name FROM my_table WHERE id=%s
 */
export const getUserById = async (req: Request, res: Response): Promise<void> => {
  const { id } = req.params as unknown as GetUserByIdParams;

  const user = await prisma.user.findUnique({
    where: { id: Number(id) },
  });

  if (!user) {
    throw new AppError(`User with id ${id} not found`, 404);
  }

  res.status(200).json({
    success: true,
    data: {
      id: user.id,
      name: user.name,
      age: user.age,
      address: user.address,
      department: user.department,
      isActive: user.isActive,
      createdAt: user.createdAt,
    },
  });
};

/**
 * GET /api/users
 *
 * Lists all registered users.
 * Useful for admin dashboards and the training pipeline.
 */
export const getAllUsers = async (_req: Request, res: Response): Promise<void> => {
  const users = await prisma.user.findMany({
    orderBy: { id: "asc" },
    select: {
      id: true,
      name: true,
      age: true,
      address: true,
      department: true,
      isActive: true,
      createdAt: true,
    },
  });

  res.status(200).json({
    success: true,
    count: users.length,
    data: users,
  });
};

/**
 * PATCH /api/users/:id
 *
 * Partially updates a user record.  Invalidates the in-memory cache
 * entry so subsequent recognition events use the updated name.
 */
export const updateUser = async (req: Request, res: Response): Promise<void> => {
  const { id } = req.params as unknown as GetUserByIdParams;
  const updates = req.body as UpdateUserInput;

  const existing = await prisma.user.findUnique({ where: { id: Number(id) } });
  if (!existing) {
    throw new AppError(`User with id ${id} not found`, 404);
  }

  const user = await prisma.user.update({
    where: { id: Number(id) },
    data: updates,
  });

  // Invalidate cache so the recognition pipeline picks up the new name.
  userCache.del(`user:${id}`);

  res.status(200).json({
    success: true,
    message: "User updated",
    data: {
      id: user.id,
      name: user.name,
      age: user.age,
      address: user.address,
      department: user.department,
      isActive: user.isActive,
      updatedAt: user.updatedAt,
    },
  });
};

/**
 * DELETE /api/users/:id
 *
 * Soft-deletes a user by setting isActive = false.
 * Hard delete would break historical attendance log foreign keys.
 */
export const deleteUser = async (req: Request, res: Response): Promise<void> => {
  const { id } = req.params as unknown as GetUserByIdParams;

  const existing = await prisma.user.findUnique({ where: { id: Number(id) } });
  if (!existing) {
    throw new AppError(`User with id ${id} not found`, 404);
  }

  await prisma.user.update({
    where: { id: Number(id) },
    data: { isActive: false },
  });

  userCache.del(`user:${id}`);

  res.status(200).json({
    success: true,
    message: `User ${id} deactivated successfully`,
  });
};
